 for(bool reversed:{false,true}){auto g=scene([&](auto&map){map.definition.playerStart={12.5f,7.5f};auto prototype=map.actorTracks[0];prototype.ai.squad=stateId("role_mixed_team");map.actorTracks.clear();for(int i=0;i<6;++i){auto actor=prototype;int role=reversed?6-i:i+1;actor.ai.role=GuardSquadRole(role);Vec2 p{6.5f,2.5f+i*2};for(auto&key:actor.keys){key.position=p;key.yaw=std::atan2(12.5f-p.x,7.5f-p.y);}actor.ai.patrol={{p,0,1000}};actor.damageState=stateId("role_damage/"+std::to_string(i));actor.deadState=stateId("role_dead/"+std::to_string(i));map.actorTracks.push_back(actor);}});tick(g,45);bool anchors=true,flankers=true;int anchor=-1;std::array<int,6> before{};
  for(size_t i=0;i<6;++i){auto role=g.npcActors()[i].track().ai.role;before[i]=g.guardFlankSide(i);bool flank=role==GuardSquadRole::Assault||role==GuardSquadRole::Rusher;if(flank)flankers&=before[i]!=0;else{anchors&=before[i]==0;if(anchor<0)anchor=int(i);}}
  check(anchors&&flankers,"Explicit mixed-team roles preserve anchors and Assault/Rusher flanks when authoring order changes");g.damageFriendly(size_t(anchor),1000,g.player().pos,{ShotKind::Player,0,0});tick(g,1);bool stable=true;for(size_t i=0;i<6;++i)if(int(i)!=anchor)stable&=g.guardFlankSide(i)==before[i];check(stable,"An anchor casualty does not reassign surviving explicit flank and support roles");
 }
 {auto g=scene([](auto&map){map.definition.playerStart={12.5f,6.5f};map.actorTracks[0].ai.role=GuardSquadRole::Rusher;map.actorTracks[0].ai.squad=stateId("role_rush_team");});tick(g,480);check(length(g.npcActors()[0].pose.position-g.player().pos)<2.4f&&g.npcActors()[0].pose.position.x>9.5f,"Rusher physically closes toward its target instead of stopping at the ordinary gun range");}
 {auto g=scene([](auto&map){map.definition.playerStart={12.5f,6.5f};map.actorTracks[0].ai.role=GuardSquadRole::Sharpshooter;map.actorTracks[0].ai.squad=stateId("role_sharp_team");});auto start=g.npcActors()[0].pose.position;tick(g,180);check(length(g.npcActors()[0].pose.position-start)<.05f&&g.player().health<100,"Sharpshooter holds a clear distant firing post and performs real attacks");g.m_player.pos={7.5f,6.5f};tick(g,120);check(g.npcActors()[0].pose.position.x<start.x-.25f&&length(g.npcActors()[0].pose.position-g.player().pos)>1.3f,"Sharpshooter backs away from close contact without advancing through the player");}
 for(int rate:{60,120}){auto g=scene([&](auto&map){medic(map);map.structures.push_back({8,5,8.2f,8,0,1});});g.setState(stateId("role_damage/1"),50);float detour=0;bool safe=true;int frames=0;
  while(g.state("role_damage/1")==50&&frames++<rate*12){tick(g,1,rate);auto pose=g.npcActors()[0].pose;detour=std::max(detour,std::fabs(pose.position.y-6.5f));safe&=g.friendlyWorld(g.npcActors()[0].level).fits(pose.position.x,pose.position.y,pose.z,1.6f);}
  report<<"medic detour Hz="<<rate<<" position="<<g.npcActors()[0].pose.position.x<<','<<g.npcActors()[0].pose.position.y<<" detour="<<detour<<" safe="<<safe<<" damage="<<g.state("role_damage/1")<<" target="<<g.state(g.friendlyKey(0,"support_target"))<<" work="<<g.state(g.friendlyKey(0,"support_ms"))<<'\n';
  check(detour>.4f&&safe&&g.state("role_damage/1")==20&&g.state(g.friendlyKey(0,"support_used"))==1,"Medic detours around low cover and spends one charge to heal thirty damage at 60/120 Hz");check(g.npcActors()[0].pose.position.x>8.2f&&length(g.npcActors()[0].pose.position-g.npcActors()[1].pose.position)<=1.4f,"Treatment occurs beside the actual living patient rather than remotely through the wall");
 }
 {auto g=scene(medic);g.setState(stateId("role_damage/1"),50);int frames=0;while(g.state(g.friendlyKey(0,"support_ms"))<300&&frames++<600)tick(g,1);check(g.state("role_damage/1")==50&&g.state(g.friendlyKey(0,"support_ms"))>=300&&g.state(g.friendlyKey(0,"support_used"))==0,"Treatment has a readable delay before healing or spending its charge");Game restored(g.m_customCampaign);bool decoded=restored.decodeSave(g.encodeSave());check(decoded&&restored.state(restored.friendlyKey(0,"support_target"))==g.state(g.friendlyKey(0,"support_target")),"Save preserves the separate support target and interrupted treatment");if(decoded){tick(g,180);tick(restored,180);check(g.state("role_damage/1")==20&&restored.state("role_damage/1")==20&&g.state(g.friendlyKey(0,"support_used"))==1&&restored.state(restored.friendlyKey(0,"support_used"))==1,"Restored treatment heals and spends exactly once without duplicating its completion event");check(std::abs(g.state(g.friendlyKey(0,"support_cooldown"))-restored.state(restored.friendlyKey(0,"support_cooldown")))<=17,"Treatment cooldown resumes within one simulation frame after saving");}}
 {auto g=scene(medic);g.setState(stateId("role_damage/1"),80);int heals=0,previous=80;for(int i=0;i<1500;++i){tick(g,1);int damage=g.state("role_damage/1");heals+=damage<previous;previous=damage;}check(heals==2&&g.state("role_damage/1")==20&&g.state(g.friendlyKey(0,"support_used"))==2,"Medic has two finite charges and never regenerates a third healing event");}
 {auto g=scene(medic);g.damageFriendly(1,200,g.player().pos,{ShotKind::Player,0,0});tick(g,300);check(g.state("role_dead/1")==1&&g.state("role_damage/1")==100&&g.state(g.friendlyKey(0,"support_used"))==0&&!g.state(g.friendlyKey(0,"support_target")),"Medic does not resurrect dead teammates or spend charges treating corpses");}
 for(int relation:{0,1,2}){auto g=scene([&](auto&map){medic(map);if(relation==0)map.actorTracks[1].ai.faction=AiFaction::Facility;if(relation==1)map.actorTracks[1].ai.faction=AiFaction::Neutral;if(relation==2)map.actorTracks[1].ai.squad=stateId("role_other_team");});g.setState(stateId("role_damage/1"),50);tick(g,240);check(g.state("role_damage/1")>=50&&g.state(g.friendlyKey(0,"support_used"))==0&&!g.state(g.friendlyKey(0,"support_target")),"Medic refuses enemies, neutrals and members of another squad");}
 {auto g=scene([&](auto&map){medic(map);map.definition.playerStart={12.5f,6.5f};for(auto&key:map.actorTracks[1].keys)key.position={6.5f,8.5f};map.actorTracks[1].ai.patrol={{{6.5f,8.5f},0,1000}};map.structures.push_back({7,7.5f,7.2f,24,0,3});});g.setState(stateId("role_damage/1"),50);g.setState(g.friendlyKey(0,"weapon_saved"),1);g.setState(g.friendlyKey(0,"weapon_rounds"),6);bool busySafe=true,observed=false,separate=false;
  for(int i=0;i<180;++i){tick(g,1);if(g.state(g.friendlyKey(0,"support_target"))){observed=true;busySafe&=g.npcWeaponPose(0).flash==0&&!g.guardFireSlot(0)&&g.state(g.friendlyKey(0,"weapon_rounds"))==6;separate|=g.guardTarget(0).kind==ShotKind::Player;}}
  check(observed&&busySafe&&separate,"Busy Medic keeps its hostile combat reference separate and releases shooting leases without spending ammunition");
 }
 for(const char*field:{"support_target","support_used","support_ms","support_fraction","support_cooldown"}){auto g=scene(medic);g.setState(g.friendlyKey(0,field),std::numeric_limits<int>::max());Game restored(g.m_customCampaign);check(!restored.decodeSave(g.encodeSave()),"Corrupt saved support targets, charges or clocks are rejected safely");}
 std::string records="--- CUSTOM_CAMPAIGN_DATA_START ---\nCAMPAIGN|Role authoring test|0\nMAP|0|Room|0|0|18.5|18.5|0|0|8|0.3||0|0|0|0|0\nLAYER|0|0|Floor|0|0\n";for(int y=0;y<24;++y)records+="ROW|0|0|"+std::to_string(y)+"|"+std::string(24,'.')+"\n";records+="TIMED_SEQUENCE|0|clock|done|0|0|24|24|-0.2|8|30000|30000|0|0|0|0|1|1\nACTOR|0|clock|0|1.6|0|0|0\nACTOR_KEY|0|0|0|6.5|6.5|0|1.57|0|0\nACTOR_KEY|0|0|30000|6.5|6.5|0|1.57|0|1\nACTOR_HEALTH|0|0|100|role_authored_damage|role_authored_dead\n";
