 auto load=[&](const std::string&tail){std::ofstream file("guard-role-authoring-fixture.txt");file<<records<<tail<<"--- CUSTOM_CAMPAIGN_DATA_END ---\n";file.close();return loadCustomCampaignFile("guard-role-authoring-fixture.txt");};auto rejects=[&](const std::string&tail){try{load(tail);return false;}catch(const std::exception&){return true;}};
 try{auto authored=load("ACTOR_ROLE|0|0|5\n"+weapon+team+ai);check(authored->maps[0]->actorTracks[0].ai.role==GuardSquadRole::Medic,"Explicit role survives record ordering before AI, faction and weapon configuration");}catch(const std::exception&){check(false,"Explicit role survives record ordering before AI, faction and weapon configuration");}
